import React, { useRef, useState, useEffect } from "react";
import { attendanceAPI } from "./api_service";

const CAPTURE_INTERVAL = 1000;

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const intervalRef = useRef(null);
  const processingRef = useRef(false);

  const [cameraReady, setCameraReady] = useState(false);
  const [autoMode, setAutoMode] = useState(true);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [frames, setFrames] = useState(0);

  // ================= CAMERA START =================
  const startCamera = async () => {
    try {
      setError(null);

      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: "user" },
        audio: false,
      });

      streamRef.current = stream;

      const video = videoRef.current;
      if (!video) throw new Error("Video not found");

      video.srcObject = stream;

      await video.play();

      setCameraReady(true);
      setAutoMode(true);

      startLoop();
    } catch (err) {
      setError("Camera access failed");
    }
  };

  // ================= LOOP STABLE =================
  const startLoop = () => {
    if (intervalRef.current) return;

    intervalRef.current = setInterval(async () => {
      if (!autoMode || processingRef.current) return;

      const video = videoRef.current;
      if (!video || video.readyState < 2) return;

      try {
        processingRef.current = true;

        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");

        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        ctx.drawImage(video, 0, 0);

        const imageBase64 = canvas.toDataURL("image/jpeg", 0.85);

        setFrames((f) => f + 1);

        // IMPORTANT: format backend correct
        const response = await attendanceAPI.recognize({
          image_base64: imageBase64,
        });

        const data = response?.data;

        if (data?.success && data?.student) {
          setResult({
            success: true,
            student: data.student,
            confidence: (data.confidence * 100).toFixed(1),
            time: new Date().toLocaleTimeString(),
          });

          if (addNotification) {
            addNotification("Detection successful", "success");
          }

          // pause after success (anti spam)
          setAutoMode(false);
          setTimeout(() => setAutoMode(true), 2500);
        }
      } catch (err) {
        console.log("frame error", err.message);
      } finally {
        processingRef.current = false;
      }
    }, CAPTURE_INTERVAL);
  };

  // ================= STOP CAMERA =================
  const stopCamera = () => {
    setAutoMode(false);

    if (intervalRef.current) clearInterval(intervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
    }

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }

    setCameraReady(false);
  };

  // ================= MANUAL CAPTURE =================
  const captureOnce = async () => {
    const video = videoRef.current;
    if (!video) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    ctx.drawImage(video, 0, 0);

    const imageBase64 = canvas.toDataURL("image/jpeg");

    const response = await attendanceAPI.recognize({
      image_base64: imageBase64,
    });

    setResult(response?.data);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  // ================= UI =================
  return (
    <div style={{ padding: 20, maxWidth: 900, margin: "auto" }}>
      <h2>Face Recognition System</h2>

      <video
        ref={videoRef}
        autoPlay
        muted
        playsInline
        style={{
          width: "100%",
          background: "#000",
          borderRadius: 10,
        }}
      />

      <div style={{ marginTop: 10, display: "flex", gap: 10 }}>
        {!cameraReady ? (
          <button onClick={startCamera}>Start Camera</button>
        ) : (
          <>
            <button onClick={captureOnce}>Capture</button>

            <button onClick={() => setAutoMode(!autoMode)}>
              {autoMode ? "Pause Auto" : "Resume Auto"}
            </button>

            <button onClick={stopCamera}>Stop</button>
          </>
        )}
      </div>

      <p>Frames processed: {frames}</p>

      {error && <p style={{ color: "red" }}>{error}</p>}

      {result && (
        <div style={{ marginTop: 20 }}>
          {result.success ? (
            <div>
              Detected: {result.student} ({result.confidence}%)
            </div>
          ) : (
            <div>Not recognized</div>
          )}
        </div>
      )}

      <canvas ref={canvasRef} style={{ display: "none" }} />
    </div>
  );
};

export default CameraRecognition;
